-- ============================================================
-- RECOVERED attendance_sessions records from the audit log
--   (logs_rows.sql -> RECORD_DELETE full deleted rows)
--
-- PRE-FLIGHT FIX: the reconstructed tables duty_type CHECK
-- constraint used lowercase values; production uses the real set
-- (SATSCAN/DAILY/NIGHT/WATCH_AND_WARD/JATHA). Fix it here so the
-- recovered rows and normal app writes both pass.
-- ============================================================

ALTER TABLE public.attendance_sessions
  DROP CONSTRAINT IF EXISTS attendance_sessions_duty_type_check;
ALTER TABLE public.attendance_sessions
  ADD CONSTRAINT attendance_sessions_duty_type_check
  CHECK (duty_type IN ('SATSCAN','DAILY','NIGHT','WATCH_AND_WARD','JATHA'));

-- id is omitted from inserts so the IDENTITY column assigns fresh ids.

ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
;

